from PIL import Image
def blob(f,cond,box):
  im=Image.open(f).convert('L'); p=im.load()
  xs=[];ys=[]
  x0,y0,x1,y1=box
  for y in range(y0,y1):
    for x in range(x0,x1):
      if cond(p[x,y]): xs.append(x); ys.append(y)
  print(f,len(xs),sum(xs)/len(xs),sum(ys)/len(ys),min(xs),max(xs),min(ys),max(ys))
