from PIL import Image
def blob(f,cond,box=(0,0,640,480)):
  im=Image.open(f).convert('L'); p=im.load()
  xs=[];ys=[]
  x0,y0,x1,y1=box
  for y in range(y0,y1):
    for x in range(x0,x1):
      if cond(p[x,y]): xs.append(x); ys.append(y)
  if xs: print(f,len(xs),round(sum(xs)/len(xs),2),round(sum(ys)/len(ys),2),min(xs),max(xs),min(ys),max(ys))
  else: print(f,'none')
for f in ['wrist_007.png','wrist_008.png']: blob(f,lambda v:v>215)
for f in ['wrist_009.png','wrist_010.png']:
  blob(f,lambda v:29<v<60,(440,150,640,330))
"

